import{_ as a,o as n,c as t,a3 as o}from"./chunks/framework.BlfGB29P.js";const s=JSON.parse('{"title":"框架实现","description":"将通用 RAG 数据链路分别映射到 LangChain 和 LlamaIndex 的核心对象与调用结果。","frontmatter":{"title":"框架实现","description":"将通用 RAG 数据链路分别映射到 LangChain 和 LlamaIndex 的核心对象与调用结果。"},"headers":[],"relativePath":"py-agent/knowledge/framework-implementation/index.md","filePath":"py-agent/knowledge/framework-implementation/index.md","lastUpdated":1785318762000}'),i={name:"py-agent/knowledge/framework-implementation/index.md"};function l(r,e,d,c,m,p){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="框架实现" tabindex="-1">框架实现 <a class="header-anchor" href="#框架实现" aria-label="Permalink to &quot;框架实现&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本分组不重新发明 RAG 原理，而是把已建立的文档、Chunk、索引、Retriever、上下文和回答契约映射到两个 Python 框架。LangChain 是本手册主线，LlamaIndex 用于理解另一种以数据和索引为中心的组织方式。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成后，你应该能够：</p><ol><li>使用 LangChain 的 <code>Document</code>、Splitter、VectorStore、Retriever 和 Runnable 组成 RAG；</li><li>使用 LlamaIndex 的 Reader、Node、<code>VectorStoreIndex</code> 和 Query Engine 组成同一链路；</li><li>找到两个框架中数据对象和运行对象的对应关系；</li><li>保留来源、错误处理和可测试边界，而不是只调用黑盒 <code>query()</code>；</li><li>根据已有技术栈选择框架，不在同一链路中无目的混用。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/py-agent/knowledge/framework-implementation/langchain-rag">LangChain RAG</a>：主线实现和 Runnable 组合。</li><li><a href="/py-agent/knowledge/framework-implementation/llamaindex-rag">LlamaIndex RAG</a>：数据框架实现与持久化。</li></ol><h2 id="_3-分组边界" tabindex="-1">3. 分组边界 <a class="header-anchor" href="#_3-分组边界" aria-label="Permalink to &quot;3. 分组边界&quot;">​</a></h2><p>示例用于映射核心对象，不覆盖所有 Loader、Embedding 和 VectorStore 集成。供应商模型和数据库选择应由项目环境决定。</p>',10)])])}const _=a(i,[["render",l]]);export{s as __pageData,_ as default};
